import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {TextAreaComponent} from "./textArea.component";
import {PI_TEXT_AREA_ACTION, PI_TEXT_AREA_CARD} from "./textArea.types";

export * from "./textArea.types";

registerCardComponent({
  name: PI_TEXT_AREA_CARD,
  component: TextAreaComponent,
  events: actionTypesToEvents(PI_TEXT_AREA_ACTION),
});

import React, {useEffect, useRef, useState} from "react";
import {type PiCardProps} from "@pihanga2/core";
import {Textarea} from "@/components/ui/textarea";
import {useFormContext} from "@/cards/form/form.context";
import {cn} from "@/lib/utils";
import type {
  CssLength,
  PiTextAreaEvents,
  PiTextAreaProps,
} from "./textArea.types";

function toCssLength(v: CssLength | undefined): string | undefined {
  if (v === undefined) return undefined;
  return typeof v === "number" ? `${v}px` : v;
}

export const TextAreaComponent = (
  props: PiCardProps<PiTextAreaProps, PiTextAreaEvents>,
): React.ReactNode => {
  const {
    name,
    value: propValue = "",
    placeholder,
    disabled,
    readOnly,
    rows = 4,
    cols,
    fieldSizing = "fixed",
    resize,
    minHeight,
    maxHeight,
    width,
    height,
    maxWidth,
    dir,
    writingMode,
    submitOnEnter,
    selfManaged = false,
    debounceMs = 0,
    className,
    style,
    autoFocus,
    cardName,
    onChanged,
    onSubmitted,
  } = props;

  // Focus the textarea once, the first time it is mounted/shown (e.g. when a
  // dialog or drawer opens). Intentionally an empty dependency array — this
  // must not re-fire on subsequent re-renders.
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  useEffect(() => {
    if (autoFocus) textareaRef.current?.focus();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // `id` may be injected by a parent pi/field card via Pihanga's extra-prop
  // forwarding. Not part of the official type so read through an escape hatch.
  const injectedId = (props as {id?: string}).id;
  const invalid = Boolean((props as {invalid?: boolean}).invalid);

  // Detect if we are inside a pi/form card via React context. When inside a
  // form, the form itself is the source of truth and buffering mechanism
  // (see pi/input, pi/text-field, etc.) — every keystroke writes straight to
  // form.formData via handleChange, and `selfManaged`/`debounceMs` are
  // ignored: there's no separate "commit" step to defer since the form's own
  // submit action is that commit point.
  const form = useFormContext();
  const useFormData = form.isInForm && Boolean(name);

  const canonicalValue = useFormData
    ? ((form.formData[name!] as string | undefined) ?? "")
    : propValue;

  // Self-managed buffering only applies in standalone mode.
  const applySelfManaged = selfManaged && !useFormData;

  // ---------------------------------------------------------------------
  // Self-managed mode (standalone only): keep an internal, always-up-to-date
  // text buffer so typing never lags, but only dispatch the outgoing
  // onChanged event on blur (and, optionally, after a trailing debounce
  // window) — not on every keystroke.
  // ---------------------------------------------------------------------
  const [localValue, setLocalValue] = useState(canonicalValue);
  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingValue = useRef<string>(canonicalValue);

  // Keep the local buffer in sync if the canonical value changes from
  // outside (e.g. a reset) while not actively editing.
  useEffect(() => {
    if (applySelfManaged) setLocalValue(canonicalValue);
  }, [canonicalValue, applySelfManaged]);

  useEffect(() => {
    return () => {
      if (debounceTimer.current != null) clearTimeout(debounceTimer.current);
    };
  }, []);

  const value = applySelfManaged ? localValue : canonicalValue;

  function commitChange(newValue: string) {
    if (useFormData) {
      form.handleChange(name!, newValue);
    } else {
      onChanged({name, value: newValue});
    }
  }

  function handleChange(e: React.ChangeEvent<HTMLTextAreaElement>) {
    const newValue = e.target.value;

    if (!applySelfManaged) {
      // Inside a form, or selfManaged not requested: commit on every
      // keystroke, matching pi/input's default (non-onCommitted) behaviour.
      commitChange(newValue);
      return;
    }

    // Self-managed (standalone): update the visible text immediately, defer
    // the outgoing event.
    setLocalValue(newValue);
    pendingValue.current = newValue;

    if (debounceMs > 0) {
      if (debounceTimer.current != null) clearTimeout(debounceTimer.current);
      debounceTimer.current = setTimeout(() => {
        debounceTimer.current = null;
        commitChange(pendingValue.current);
      }, debounceMs);
    }
  }

  function handleBlur() {
    if (!applySelfManaged) return;
    if (debounceTimer.current != null) {
      clearTimeout(debounceTimer.current);
      debounceTimer.current = null;
    }
    commitChange(pendingValue.current);
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (
      submitOnEnter &&
      e.key === "Enter" &&
      !e.shiftKey &&
      !e.ctrlKey &&
      !e.metaKey &&
      !e.altKey
    ) {
      e.preventDefault();
      const currentValue = e.currentTarget.value;
      if (applySelfManaged && debounceTimer.current != null) {
        clearTimeout(debounceTimer.current);
        debounceTimer.current = null;
        commitChange(currentValue);
      }
      if (useFormData) {
        // Inside a form, form.formData is already current (every keystroke
        // wrote through handleChange), so request the form-level submit —
        // consistent with pi/input's and pi/text-field's submitOnEnter.
        form.requestAction("submit");
      } else {
        onSubmitted({name, value: currentValue});
      }
    }
  }

  // Default resize behaviour: content-sizing boxes shouldn't be manually
  // resizable (dragging writes an inline width/height that permanently
  // defeats field-sizing: content).
  const resolvedResize =
    resize ?? (fieldSizing === "content" ? "none" : "vertical");

  const resizeClass =
    resolvedResize === "none"
      ? "resize-none"
      : resolvedResize === "vertical"
        ? "resize-y"
        : resolvedResize === "horizontal"
          ? "resize-x"
          : "resize";

  // `field-sizing` is expressed as a Tailwind utility class (shipped by
  // Tailwind v4) rather than an inline style — this is both more idiomatic
  // for this codebase (the base Textarea already defaults to
  // `field-sizing-content`) and avoids relying on very new CSS properties
  // being present in every CSSStyleDeclaration IDL implementation.
  const fieldSizingClass =
    fieldSizing === "content" ? "field-sizing-content" : "field-sizing-fixed";

  const inlineStyle: React.CSSProperties = {
    minHeight: toCssLength(minHeight),
    maxHeight: toCssLength(maxHeight),
    width: toCssLength(width),
    height: toCssLength(height),
    maxWidth: toCssLength(maxWidth),
    writingMode,
    ...style,
  };

  // Use the id injected by pi/field (for label↔control linking); fall back
  // to a locally-generated id when used standalone.
  const selfId = `${cardName}-${name ?? "field"}`;
  const fieldId = injectedId ?? selfId;

  return (
    <Textarea
      ref={textareaRef}
      id={fieldId}
      value={value}
      onChange={handleChange}
      onBlur={handleBlur}
      onKeyDown={handleKeyDown}
      placeholder={placeholder}
      disabled={disabled}
      readOnly={readOnly}
      rows={fieldSizing === "fixed" ? rows : undefined}
      cols={fieldSizing === "fixed" ? cols : undefined}
      dir={dir}
      aria-invalid={invalid || undefined}
      data-pihanga={cardName}
      className={cn(fieldSizingClass, resizeClass, className)}
      style={inlineStyle}
    />
  );
};

import type {CSSProperties} from "react";
import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";
import type {FormFieldProps} from "@/cards/form/form.types";

export const PI_TEXT_AREA_CARD = "pi/text-area";

export const TextArea = createCardDeclaration<
  PiTextAreaProps,
  PiTextAreaEvents
>(PI_TEXT_AREA_CARD);

export const PI_TEXT_AREA_ACTION = registerActions(PI_TEXT_AREA_CARD, [
  "changed",
  "submitted",
]);

export const onTextAreaChanged = createOnAction<PiTextAreaChangedEvent>(
  PI_TEXT_AREA_ACTION.CHANGED,
);

export const onTextAreaSubmitted = createOnAction<PiTextAreaSubmittedEvent>(
  PI_TEXT_AREA_ACTION.SUBMITTED,
);

/** A CSS length. Numbers are treated as pixels, strings are used verbatim. */
export type CssLength = number | string;

/**
 * How the textarea sizes itself:
 *  - "fixed"   (default) — plain `<textarea>` behaviour. Size is governed by
 *              `rows`/`cols` (and any explicit `width`/`height`); the user
 *              may resize it per the `resize` prop. Never grows with content.
 *  - "content" — uses the CSS `field-sizing: content` behaviour: the box
 *              grows/shrinks to fit its content, clamped by any
 *              `minHeight`/`maxHeight`/`width`/`height`/`maxWidth` you set.
 *              `rows`/`cols` are ignored by the browser once this is active.
 */
export type PiTextAreaFieldSizing = "fixed" | "content";

export type PiTextAreaResize = "none" | "vertical" | "horizontal" | "both";

export type PiTextAreaProps = FormFieldProps & {
  /**
   * Controlled value used in standalone mode (outside a Form).
   * Ignored when `name` is set and the component is inside a pi/form.
   */
  value?: string;

  /** Placeholder text shown when the box is empty. May contain `\n`. */
  placeholder?: string;

  /** When true, the textarea is disabled and non-interactive. */
  disabled?: boolean;

  /** When true, the textarea's value cannot be edited by the user. */
  readOnly?: boolean;

  /**
   * Number of visible text lines. Only meaningful when `fieldSizing` is
   * `"fixed"` — browsers ignore `rows`/`cols` once `field-sizing: content`
   * is active. Default: `4`.
   */
  rows?: number;

  /** Number of visible character columns. See `rows` for caveats. */
  cols?: number;

  /** See `PiTextAreaFieldSizing`. Default: `"fixed"`. */
  fieldSizing?: PiTextAreaFieldSizing;

  /**
   * CSS `resize` behaviour — whether/how the user can drag-resize the box.
   * Default: `"vertical"` when `fieldSizing` is `"fixed"`, `"none"` when
   * `fieldSizing` is `"content"` (dragging would otherwise permanently
   * defeat the content-based sizing by writing an inline width/height).
   */
  resize?: PiTextAreaResize;

  /** Minimum height. Accepts CSS units like `"2lh"`, `"4rem"`, or a number of px. */
  minHeight?: CssLength;

  /** Maximum height. Once reached, content scrolls instead of growing further. */
  maxHeight?: CssLength;

  /** Explicit width. Freezes the inline axis even when `fieldSizing="content"`. */
  width?: CssLength;

  /** Explicit height. Freezes the block axis even when `fieldSizing="content"`. */
  height?: CssLength;

  /**
   * Maximum width — a guard against an unconstrained `fieldSizing="content"`
   * box escaping its parent container.
   */
  maxWidth?: CssLength;

  /** Text direction. Default: inherited from the document. */
  dir?: "ltr" | "rtl";

  /**
   * CSS `writing-mode`. With `"vertical-rl"` the sizing axes swap: content
   * growth under `fieldSizing="content"` runs horizontally, not vertically.
   */
  writingMode?: "horizontal-tb" | "vertical-rl" | "vertical-lr";

  /**
   * When true, pressing Enter (without Shift/Ctrl/Meta/Alt) submits instead
   * of inserting a newline. Shift+Enter (etc.) still inserts a newline.
   *
   * - Inside a `pi/form` (i.e. `name` is set and a `pi/form` ancestor is
   *   present): requests the form's submit action
   *   (`FormContext.requestAction("submit")`) — equivalent to clicking a
   *   `Button` with `formAction: "submit"`, and consistent with
   *   `pi/input`'s / `pi/text-field`'s `submitOnEnter`.
   * - Standalone: fires this card's own `onSubmitted` event with the
   *   current text.
   *
   * Default: `false`.
   */
  submitOnEnter?: boolean;

  /**
   * **Standalone mode only** (ignored when used inside a `pi/form` card —
   * see below). When true, the textarea keeps its own internal text state
   * so the visible text always updates immediately as the user types, but
   * the outgoing `onChanged` event is only dispatched at a "commit" point
   * instead of on every keystroke:
   *
   *  - always on blur,
   *  - and, if `debounceMs > 0`, also after that many ms of typing
   *    inactivity (a trailing debounce), so the value is committed even if
   *    the user never blurs the field (e.g. drives an autosave / API call).
   *
   * Use this to avoid flooding the host app / reducer with an event per
   * keystroke for a card whose `onChanged` handler is expensive.
   *
   * When the card is used inside a `pi/form` (i.e. `name` is set and a
   * `pi/form` ancestor is present), this prop has no effect: form fields
   * always write back to form state on every keystroke via
   * `form.handleChange`, exactly like `pi/input` and `pi/text-field` — the
   * form's own submit action is the natural "commit" point in that case.
   *
   * Default: `false` (dispatches `onChanged` on every keystroke, as
   * before).
   */
  selfManaged?: boolean;

  /**
   * Trailing-debounce window (ms) for committing changes while
   * `selfManaged` is true (standalone mode only). `0` (default) means no
   * debounce — the value is only committed on blur. Ignored when
   * `selfManaged` is `false`, or when the card is inside a `pi/form`.
   */
  debounceMs?: number;

  /** Additional class names merged onto the root `<textarea>`. */
  className?: string;

  /** Additional inline styles merged onto the root `<textarea>` (highest precedence). */
  style?: CSSProperties;

  /**
   * When true, the textarea grabs keyboard focus the first time it is
   * mounted/shown (e.g. when a dialog or drawer opens). Only applies once,
   * on mount — it does not re-focus on subsequent re-renders.
   */
  autoFocus?: boolean;
};

export type PiTextAreaChangedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** New value after the change. */
  value: string;
};

export type PiTextAreaSubmittedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** The current text at the time Enter was pressed. */
  value: string;
};

export type PiTextAreaEvents = {
  onChanged: PiTextAreaChangedEvent;
  onSubmitted: PiTextAreaSubmittedEvent;
};
